    _silver.update({"id": f"{_weapon['id']}_prata", "name": f"{_weapon['name']} de Prata",
                    "price": int(_weapon.get("price", 0) or 0) * 10, "silver": True,
                    "corrosion_max": 5, "corrosion_free_levels": 2})
    SHOP_WEAPONS.append(_silver)

