def slots_max_para(p):
    """MÃ¡ximo de slots por cÃ­rculo do jogador, pela tabela de nÃ­vel (cap no 5)."""
    nivel = min(max(p.get("level", 1), 1), 5)
    return SLOTS_POR_NIVEL[nivel]

