_CR_POR_TIER = {1: 0.5, 2: 1.0, 3: 2.0, 4: 5.0}

def monster_cr(mdef):
    """NÃ­vel de Desafio (cr) unificado do monstro. Usa o cr explÃ­cito quando
    presente; senÃ£o cai para um valor derivado do tier. Fonte Ãºnica da verdade."""
    cr = mdef.get("cr")
    if cr is not None:
        try:
            return float(cr)
        except (TypeError, ValueError):
            pass
    return _CR_POR_TIER.get(mdef.get("tier", 1), 1.0)

TRAP_XP_POR_CR = 20

def trap_cr(meta):
    """cr unificado da armadilha (Camada C). Usa o cr explÃ­cito quando presente;
    senÃ£o deriva da dificuldade do save (DC 8â†’0.0 â€¦ escala suave, teto 1.0);
    sem nenhum dos dois, default 0.3. Fonte Ãºnica da verdade."""
    cr = meta.get("cr")
    if cr is not None:
        try:
            return float(cr)
        except (TypeError, ValueError):
            pass
    dif = meta.get("dificuldade")
    if isinstance(dif, (int, float)) and not isinstance(dif, bool):
        return max(0.1, min(1.0, round((dif - 8) / 6.0, 2)))
    return 0.3

def trap_xp(cr):
    """XP de uma armadilha derivado do seu cr (dividido entre os herÃ³is vivos)."""
    return round(float(cr) * TRAP_XP_POR_CR)

def _aplicar_equipamentos_monstro(m):
    """Equipa a criatura com itens da mesma loja usada pelos herÃ³is.

    A ficha guarda apenas IDs; cada instÃ¢ncia recebe cÃ³pias independentes para
    que poÃ§Ãµes e doses de veneno possam ser consumidas sem alterar o catÃ¡logo.
    """
    if not m.get("equipment_enabled"):
        return
    subtipo = m.get("subtipo", _subtipo_padrao_monstro(m))
    if subtipo not in {"raca_padrao", "abissal", "morto_vivo"}:
        return
    items, seen = [], set()
    for item_id in m.get("equipped_items", m.get("equipment", [])):
        if item_id in seen or item_id not in _DUNGEON_ITEM_CATALOG:
            continue
        seen.add(item_id)
        items.append(deepcopy(_DUNGEON_ITEM_CATALOG[item_id]))
    m["equipment_items"] = items
    if not items:
        return

    weapon = next((item for item in items if item.get("die")), None)
    if weapon:
        configured_attack = (m.get("attacks") or [{}])[0]
        attr = "dex" if weapon.get("stat") == "dex" else "str_"
        atk_bonus = int(m.get("base_attack_bonus", 0)) + mod(m.get(attr, 10))
        m["attacks"] = [{
            "name": weapon.get("name", "Arma"), "atk_bonus": atk_bonus,
            "damage": weapon["die"], "damage_types": [DMG_PHYSICAL],
            "num_attacks": 1, "attack_attribute": attr,
            "damage_attribute": attr, "apply_attribute_damage": True,
            "attribute_mod_base": mod(m.get(attr, 10)),
            "base_attack_bonus": int(m.get("base_attack_bonus", 0)),
            "range": weapon.get("range"), "reach": weapon.get("reach"),
            "categoria": weapon.get("categoria"),
            "on_hit": configured_attack.get("on_hit"),
            "on_hit_effect": configured_attack.get("on_hit_effect"),
            "poison_dc": configured_attack.get("poison_dc"),
            "extra_damage": configured_attack.get("extra_damage"),
            "extra_damage_types": configured_attack.get("extra_damage_types", []),
        }]
        m["equipped_weapon"] = weapon

    ac_bonus = sum(int(item.get("ac_bonus", 0) or 0) for item in items)
    ac_bonus += sum(int(item.get("value", 0) or 0) for item in items if item.get("effect") == "def_")
    if ac_bonus:
        m["ac"] += ac_bonus
        m["equipment_ac_bonus"] = ac_bonus
    atk_bonus = sum(int(item.get("value", 0) or 0) for item in items if item.get("effect") == "atk")
    if atk_bonus:
        m["equipment_attack_bonus"] = atk_bonus
    hp_bonus = sum(int(item.get("value", 0) or 0) for item in items if item.get("effect") == "maxhp")
    if hp_bonus:
        m["max_hp"] += hp_bonus
        m["hp"] += hp_bonus
        m["equipment_hp_bonus"] = hp_bonus
    move_bonus = sum(int(item.get("value", 0) or 0) for item in items if item.get("effect") == "spd")
    if move_bonus:
        m["movement"] += move_bonus
        m["equipment_movement_bonus"] = move_bonus
    poison = next((item.get("veneno_id") for item in items if item.get("effect") == "coat_poison" and item.get("veneno_id")), None)
    if poison and m.get("attacks"):
        m["attacks"][0]["on_hit"] = poison
        m["equipment_poison"] = poison
    m["equipment_consumables"] = [item for item in items if item.get("item_slot") == "bag"]

def make_monster(mdef, room):
    m = deepcopy(mdef)
    # Mesmo campo usado pelo editor: os despachantes do grimÃ³rio leem `level`.
    # Mantemos ambos para compatibilidade com as fÃ³rmulas de herÃ³i.
    m["caster_level"] = max(1, int(m.get("caster_level", m.get("level", 1))))
    m["level"] = m["caster_level"]
    # CA de monstros segue a mesma base D20: 10 + DES + Armadura Natural.
    # Fichas legadas sem o novo campo preservam exatamente a CA que jÃ¡ tinham.
    m["natural_armor"] = max(0, int(m.get("natural_armor",
        int(m.get("ac", 10)) - 10 - mod(m.get("dex", 10)))))
    m["ac"] = max(1, 10 + mod(m.get("dex", 10)) + m["natural_armor"])
    # VisÃ£o: as fichas legadas que jÃ¡ possuÃ­am darkvision_range mantÃªm a
    # caracterÃ­stica VisÃ£o no Escuro, mas agora usam o mesmo raio calculado
    # por atributos de todos os monstros.
    # O padrÃ£o Ã© 6, mas algumas fichas podem declarar uma exceÃ§Ã£o explÃ­cita.
    m["base_movement"] = int(m.get("movement", 6)) if m.get("movement_exception") else 6
    m["movement"] = m["base_movement"]
    m["vision_base"] = max(-30, min(30, int(m.get("vision_base", 0))))
    m["visao_escuro"] = bool(m.get("visao_escuro") or m.get("darkvision_range"))
    m["id"] = new_id()
    m["max_hp"] = m["hp"]
    m["pos"] = [room["cx"], room["cy"]]
    m["room_id"] = room["id"]
    _aplicar_equipamentos_monstro(m)
    # Inicializa contadores de habilidades especiais (formato novo)
    if "special_abilities" in m:
        m["ability_uses"] = {
            ab["id"]: (ab["uses_per_day"] if ab.get("uses_per_day") is not None else ab["uses_per_combat"])
            for ab in m["special_abilities"]
            if ab.get("uses_per_day") is not None or ab.get("uses_per_combat") is not None
        }
        m["ability_cooldowns"] = {}
        # Habilidades vindas do editor tÃªm dois limites independentes. Esses
        # contadores nÃ£o interferem nas IAs nativas que jÃ¡ usam ability_uses.
        m["monster_ability_uses"] = {
            ab["id"]: ab.get("uses_per_day", 1) for ab in m["special_abilities"]
            if ab.get("source") in {"heroi", "guilda"}
        }
        m["monster_ability_cooldowns"] = {}
    # Magias sÃ£o configuradas separadamente das habilidades. Fichas antigas
    # continuam vÃ¡lidas: suas entradas action_type=magia sÃ£o convertidas aqui.
    spell_defs = m.get("monster_spells")
    if not isinstance(spell_defs, list):
        spell_defs = []
    if not spell_defs:
        spell_defs = [
            {"id": ab["id"], "limit_mode": "cooldown" if ab.get("cooldown_turns") is not None else "encounter",
             "uses_per_combat": ab.get("uses_per_combat", 1), "cooldown_turns": ab.get("cooldown_turns", 1)}
            for ab in m.get("special_abilities", []) if ab.get("action_type") == "magia" and ab.get("id") in GRIMORIO
        ]
    m["monster_spells"] = spell_defs
    m["spell_uses"] = {s["id"]: max(1, int(s.get("uses_per_combat", 1))) for s in spell_defs
                       if s.get("id") in GRIMORIO and s.get("limit_mode", "encounter") != "cooldown"}
    m["spell_cooldowns"] = {}
    # â”€â”€ Goblins: muniÃ§Ã£o do arqueiro, escolha de arma do combatente, arremesso â”€â”€
    if m.get("type") == "goblin_arqueiro":
        m["flechas"] = 10
        m["pode_arremessar"] = False
    if m.get("type") == "goblin_combatente":
        if random.random() < 0.5:
            m["attacks"] = [{"name": "Adaga", "atk_bonus": 4, "damage": "1d4+2",
                             "damage_types": ["physical"], "num_attacks": 1,
                             "on_hit": None, "categoria": "perfurante"}]
            m["guaranteed_loot"] = ["dagger"]
        else:
            m["attacks"] = [{"name": "Espada Curta", "atk_bonus": 2, "damage": "1d6",
                             "damage_types": ["physical"], "num_attacks": 1,
                             "on_hit": None, "categoria": "cortante"}]
            m["guaranteed_loot"] = ["shortsword", "dagger"]
        m["pode_arremessar"] = True
    if m.get("type") == "goblin_dual":
        m["pode_arremessar"] = True
    # â”€â”€ Kobold Lanceiro: lanÃ§a envenenada + doses extras â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    if m.get("type") == "kobold_lanceiro":
        m["veneno_arma_ativo"]  = True               # 1 dose jÃ¡ aplicada na lanÃ§a
        m["veneno_arma_id"]     = "veneno_aranha_sombria"
        m["veneno_doses_extras"] = random.randint(1, 3)   # 1â€“3 frascos extras
        m["covardia_testada"]   = False
        m["kobold_medo"]        = False
        m["kobold_medo_rodadas"] = 0
    # â”€â”€ Kobold Besteiro: virotes normais + 10% de virotes especiais â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    if m.get("type") == "kobold_besteiro":
        m["virotes"]            = 10
        m["virotes_especiais_tipo"]  = None
        m["virotes_especiais_count"] = 0
        if random.randint(1, 100) <= 10:
            tipo_roll = random.randint(1, 2)
            m["virotes_especiais_tipo"]  = ("veneno_escorpiao_pedra" if tipo_roll == 1
                                             else "incendiario")
            m["virotes_especiais_count"] = roll_dice("1d4")
        m["covardia_testada"]   = False
        m["kobold_medo"]        = False
        m["kobold_medo_rodadas"] = 0
    # â”€â”€ Esqueleto Humano: sorteia arma ao criar â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    if m.get("type") == "esqueleto_humano":
        _roll = random.randint(1, 100)
        if _roll <= 30:
            _nome, _die, _cat, _range = "Espada Curta",  "1d6",  "cortante",   None
            m["esqueleto_arma_id"] = "shortsword"
        elif _roll <= 60:
            _nome, _die, _cat, _range = "LanÃ§a",         "1d6",  "perfurante", 2
            m["esqueleto_arma_id"] = "lanca_curta"
        elif _roll <= 70:
            _nome, _die, _cat, _range = "Espada Longa",  "1d8",  "cortante",   None
            m["esqueleto_arma_id"] = "longsword"
        elif _roll <= 80:
            _nome, _die, _cat, _range = "Espada Curta",  "1d6",  "cortante",   None
            m["esqueleto_arma_id"] = "shortsword"
            m["ac"] += 2   # escudo: CA 12 â†’ 14
            m["esqueleto_escudo"] = True
        elif _roll <= 90:
            _nome, _die, _cat, _range = "LanÃ§a",         "1d6",  "perfurante", 2
            m["esqueleto_arma_id"] = "lanca_curta"
            m["ac"] += 2   # escudo: CA 12 â†’ 14
            m["esqueleto_escudo"] = True
        elif _roll <= 95:
            _nome, _die, _cat, _range = "Machado",       "1d10", "cortante",   None
            m["esqueleto_arma_id"] = "machado_basico"
        else:
            _nome, _die, _cat, _range = "Espada 2 MÃ£os", "1d10", "cortante",   None
            m["esqueleto_arma_id"] = "espada2m"
        atk = {"name": _nome, "atk_bonus": 2, "damage": _die,
               "damage_types": ["physical"], "num_attacks": 1, "on_hit": None,
               "categoria": _cat}
        if _range:
            atk["range"] = _range
        m["attacks"] = [atk]
    return m

def spawn_monsters_for_room(room, player_count):
    tier = 1 if room["role"] == "monster" else 4
    is_boss = (tier == 4)
    # Salas normais: apenas monstros com ficha completa (ai_type definido).
    # Monstros legado sem ai_type nÃ£o tÃªm attacks list e nÃ£o funcionam no novo sistema.
    # Sala do boss: usa o pool antigo sem filtro (dragÃ£o ainda Ã© legado).
    pool = [m for m in MONSTER_DEFS
            if m.get("boss", False) == is_boss
            and m.get("spawn_max", 1) > 0
            and (is_boss or "ai_type" in m)]
    if not pool:
        return []
    if tier == 4:
        boss_def = next(m for m in MONSTER_DEFS if m.get("boss"))
        return [make_monster(boss_def, room)]
    mdef = random.choice(pool)
    min_c = mdef.get("spawn_min", 1)
    max_c = mdef.get("spawn_max", min(3, player_count))
    # Teto nunca abaixo do piso: com poucos jogadores (ex.: solo) um monstro com
    # spawn_min=2 produzia randint(2, 1) â†’ ValueError e a masmorra nÃ£o abria.
    count = random.randint(min_c, max(min_c, min(max_c, player_count)))
    monsters = [make_monster(mdef, room) for _ in range(count)]
    # Companion spawn: aceita um Ãºnico `spawn_companion` (ex.: kobold) ou uma
    # lista `spawn_companions` (ex.: bando do Goblin Dual: combatentes + arqueiros).
    companions = list(mdef.get("spawn_companions", []))
    if mdef.get("spawn_companion"):
        companions.append(mdef["spawn_companion"])
    for companion in companions:
        comp_def = next((d for d in MONSTER_DEFS if d["type"] == companion["type"]), None)
        if comp_def:
            n = random.randint(companion["min"], companion["max"])
            monsters.extend(make_monster(comp_def, room) for _ in range(n))
    return monsters

def make_trap(room, tiles):
    # Sorteia uma casa de CHÃƒO dentro da sala (evita as bordas que viraram
    # parede ao posicionar as portas â€” uma armadilha na parede nunca dispara).
    floors = [[x, y]
              for y in range(room["y"], room["y"] + room["h"])
              for x in range(room["x"], room["x"] + room["w"])
              if tiles[y][x] == FLOOR]
    pos = random.choice(floors) if floors else [room["cx"], room["cy"]]
    return {"id": new_id(), "pos": pos,
            "damage": random.randint(4, 8), "triggered": False, "room_id": room["id"]}

def preco_pergaminho(circulo_nome, nivel, int_bonus):
    """PreÃ§o = base do cÃ­rculo Ã— multiplicador de nÃ­vel + acrÃ©scimo de INT.
    multiplicador = (nÃ­vel de conjurador âˆ’ nÃ­vel mÃ­nimo do cÃ­rculo) + 1."""
    base   = PERGAMINHO_PRECO_BASE.get(circulo_nome, 20)
    min_lv = PERGAMINHO_NIVEL_CIRCULO.get(circulo_nome, 1)
    mult   = max(1, (nivel - min_lv) + 1)
    return base * mult + PERGAMINHO_INT_SURCHARGE.get(int_bonus, 0)

def preview_pergaminho(magia, nivel, int_bonus):
    """Calcula a prÃ©via exibÃ­vel de um pergaminho (dano/alcance/CD no nÃ­vel +
    bÃ´nus de INT marcados). Usa os campos estruturados do GRIMORIO."""
    circ_num = {"primeiro": 1, "segundo": 2, "terceiro": 3}.get(magia.get("circulo", "primeiro"), 1)
    # Alcance (fixo, ou base + escalaÃ—(nÃ­vel-1)); None = pessoal/Ã¡rea no caster.
    if "alcance" in magia:
        alcance = magia["alcance"]
    elif "alcance_base" in magia:
        alcance = magia["alcance_base"] + magia.get("alcance_escala", 0) * (nivel - 1)
    else:
        alcance = None
    # Dano: "dano_por_nivel" (XdY Ã— nÃ­vel) ou "dano_base" (+ "dano_escala" a cada 2 nÃ­veis).
    dano = None
    def _mult_dado(dado, fator):
        try:
            n, face = str(dado).lower().split("d"); return f"{int(n) * fator}d{face}"
        except Exception:
            return f"{fator}Ã—{dado}"
    if magia.get("dano_por_nivel"):
        dano = _mult_dado(magia["dano_por_nivel"], nivel)
    elif magia.get("dano_base"):
        base = magia["dano_base"]; esc = magia.get("dano_escala")
        try:
            bn, bf = str(base).lower().split("d")
            total = int(bn) + (int(str(esc).lower().split("d")[0]) * (nivel // 2) if esc else 0)
            dano = f"{total}d{bf}"
        except Exception:
            dano = base
    return {
        "nivel": nivel,
        "int_bonus": int_bonus,
        "dano": dano,
        "alcance": alcance,
        "area_raio": magia.get("area_raio"),
        "cd": (8 + int_bonus + circ_num) if magia.get("save") else None,
        "save": magia.get("save"),
        "duracao": magia.get("duracao"),
        "efeito": magia.get("descricao") if not dano else None,
    }

def _num_dados_dano(dano_str):
    """Quantidade de dados de uma string 'XdY' (0 se nÃ£o houver)."""
    try:
        return int(str(dano_str).lower().split("d")[0])
    except Exception:
        return 0

def gerar_pergaminho(circulo_num=1, classe=None, nivel=None, int_bonus=0,
                     magia_id=None, talentos=None):
    """Cria um item de pergaminho com uma magia implementada do cÃ­rculo dado.
    `nivel` = nÃ­vel de conjurador (default = mÃ­nimo do cÃ­rculo; escala dano/alcance
    e entra no cÃ¡lculo de falha). `int_bonus` = modificador de INT (+0..+5; afeta a
    CD e o dano). `talentos` = dict {cd,duracao,dano} de metamagias do Pedro JÃ
    GRAVADAS no pergaminho (aplicadas sÃ³ onde fazem sentido). Inclui o preÃ§o."""
    nome_circ = PERGAMINHO_CIRCULO_NOME.get(circulo_num, "primeiro")
    if magia_id and magia_id in GRIMORIO_IMPLEMENTADAS:
        sid = magia_id
        nome_circ = GRIMORIO[sid]["circulo"]
    else:
        elig = [s for s in GRIMORIO_IMPLEMENTADAS
                if GRIMORIO[s]["circulo"] == nome_circ
                and (classe is None or classe in GRIMORIO[s].get("classe", []))]
        if not elig:
            return None
        sid = random.choice(elig)
    mg     = GRIMORIO[sid]
    min_lv = PERGAMINHO_NIVEL_CIRCULO[nome_circ]
    nivel  = min_lv if nivel is None else max(min_lv, min(PERGAMINHO_NIVEL_MAX, nivel))
    int_bonus = max(0, min(PERGAMINHO_INT_MAX, int_bonus))
    pv = preview_pergaminho(mg, nivel, int_bonus)

    # Talentos do Pedro gravados â€” sÃ³ valem onde aplicÃ¡veis (save / duraÃ§Ã£o / dano).
    req = talentos or {}
    t_cd   = bool(req.get("cd"))      and bool(mg.get("save"))
    t_dur  = bool(req.get("duracao")) and bool(mg.get("duracao"))
    t_dano = bool(req.get("dano"))    and bool(mg.get("dano_por_nivel") or mg.get("dano_base"))

    preco = preco_pergaminho(nome_circ, nivel, int_bonus)
    if t_cd:   preco += 50
    if t_dur:  preco += 50
    if t_dano: preco += 20 * _num_dados_dano(pv.get("dano"))

    # Reflete os talentos na prÃ©via (CD +1; dano Ã—1.5; duraÃ§Ã£o estendida).
    if t_cd and pv.get("cd") is not None:
        pv["cd"] += 1
    pv["talento_cd"], pv["talento_duracao"], pv["talento_dano"] = t_cd, t_dur, t_dano

    suf = []
    if nivel > min_lv:    suf.append(f"Nv{nivel}")
    if int_bonus > 0:     suf.append(f"INT+{int_bonus}")
    if t_dano:            suf.append("DanoÃ—1.5")
    if t_cd:              suf.append("CD+1")
    if t_dur:             suf.append("Dur+")
    nome = f"Pergaminho: {mg['nome']}" + (f" ({', '.join(suf)})" if suf else "")
    return {
        "id": f"pergaminho_{sid}", "name": nome,
        "emoji": "ðŸ“œ", "item_slot": "bag", "effect": "scroll",
        "magia_id": sid, "circulo": nome_circ,
        "nivel_conjurador": nivel, "int_bonus": int_bonus,
        "talento_cd": t_cd, "talento_duracao": t_dur, "talento_dano": t_dano,
        "price": preco,
        "preview": pv,
    }

# â”€â”€â”€ GAME ROOM â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

class GameRoom:
    def __init__(self, code):
        self.code = code
        self.connections = {}   # pid -> websocket
        self.players = {}       # pid -> player dict
        self.master_pid = None     # pid do mestre humano (Modo Mestre) ou None
        self.master_name = None    # nome do mestre (p/ rejoin)
        self.master_manual_mid = None       # id do monstro na janela Manual (ou None)
        self.master_manual_event = None     # asyncio.Event que fecha a janela
        self.master_manual_timer = None     # tarefa do timeout anti-AFK
        self.master_reserve = {}   # Camada B: typeâ†’count restante de reforÃ§os do mestre
        self.expected_party = {"heroes": 4, "level": 1}   # Camada C: grupo esperado (referÃªncia)
        self.player_order = []  # list of pid in turn order
        self.phase = "lobby"    # lobby | character_select | playing | ended
        self.host_pid = None
        self.tiles = None
        self.rooms = []
        # True depois que a masmorra da expediÃ§Ã£o foi gerada. Enquanto for True,
        # toda volta da cidade RETOMA a mesma masmorra (mapa/monstros/baÃºs/portas/
        # nÃ©voa/armadilhas intactos) em vez de regenerar. Volta a False quando a
        # masmorra Ã© concluÃ­da (boss derrotado â†’ end_game), liberando uma nova.
        self.dungeon_generated = False
        # Tamanho do tabuleiro (procedural = 30Ã—30; masmorra autorada define o seu).
        self.map_w = MAP_W
        self.map_h = MAP_H
        # SeleÃ§Ã£o de masmorra no lobby (Fase 1 do editor).
        self.mode = "procedural"          # "procedural" | "authored"
        self.selected_dungeon = None      # nome do arquivo em dungeons/ (modo authored)
        self.dungeon_def = None           # dict cru da masmorra autorada carregada
        # Preset de iluminaÃ§Ã£o do 3D no cliente ("penumbra"|"masmorra"|"ar_livre").
        # Procedural usa o padrÃ£o; masmorra autorada sobrescreve em load_authored_dungeon.
        self.ambiente = "masmorra"
        # Fase 3 â€” objetivos/prisioneiro/saÃ­da (sÃ³ em masmorra autorada).
        self.exit_pos = None
        self.objectives = None
        self.objective_status = None
        self.prisoner = None
        self.rescue_failed = False
        self._objetivo_concluido = False
        self.mission_complete_pending = False
        self.salas_visitadas = set()   # room_ids visitados (objetivo salas_obrigatorias)
        # Fase 4a â€” campanha.
        self.campaign = None         # dict carregado (modo "campaign")
        self.campaign_phase = 0      # Ã­ndice da fase atual em campaign["dungeons"]
        self.selected_campaign = None  # nome do arquivo da campanha selecionada (lobby)
        self._campaign_outro = None   # beat de encerramento pendente (cidade), ou None
        self.key_chest_opened = False
        self.monsters = {}      # id -> monster
        self.corpses = {}       # id -> cadÃ¡ver (monstro morto, alvo de Animar Mortos)
        self.animados_phase_pid = None  # pid no "turno dos servos" (logo apÃ³s o mago)
        self.last_stand_pid = None      # pid na sub-fase do Ãšltimo EsforÃ§o (ou None)
        self.last_stand_event = None    # asyncio.Event sinalizado ao fechar a janela
        self.last_stand_timer_task = None
        self.traps = []
        self.armadilhas = []    # armadilhas colocÃ¡veis (ver ARMADILHAS) â€” distintas de self.traps
        self._armadilha_seq = 0 # contador p/ ids Ãºnicos de armadilha
        self.zonas_especiais = []  # zonas mÃ¡gicas (escuridÃ£o/silÃªncio) â€” ver GRIMORIO/handle_magia
        self.turn_index = 0
        self.round_num = 1
        # Ordem individual de iniciativa: [{kind:"player"|"monster", id, ...}].
        # Ã‰ recalculada no inÃ­cio de cada rodada, pois DES/INT podem mudar.
        self.initiative_order = []
        self.initiative_index = 0
        self.initiative_active = False
        self.initiative_task = None
        # Timer de turno (30s): tarefa asyncio + token p/ descartar timers velhos.
        self.TURN_LIMIT_S = 30
        self.MASTER_MANUAL_MOVE = 5       # passos por turno de um monstro em modo Manual
        self.MASTER_MANUAL_LIMIT_S = 60   # timeout anti-AFK do mestre por monstro manual
        self.turn_timer_task = None
        self.turn_token = 0
        self.turn_timer_started_ms = None   # epoch ms do inÃ­cio do turno atual (p/ contagem no cliente)
        self.gm_log = []        # narrative messages
        self.explored = set()   # (x,y) tuples visible to all
        self.door_rooms = {}    # (x,y) -> [room_id,...] â€” salas que cada porta destranca
        self.magic_reveal = {}  # (x,y) -> rodada de expiraÃ§Ã£o (ClarividÃªncia revela interior)
        self.stairs_pos = None  # [x, y] â€” entrance staircase tile
        self.temp_def = {}      # pid -> bonus_def (lasts 1 turn)
        self.temp_def_turnos = {}  # pid -> turnos restantes (>1 = duraÃ§Ã£o estendida; Aprimorar Magia do mago)
        self.smoke = {}         # mid -> True (monsters miss next attack)
        self.immune = {}        # pid -> turns_remaining
        self.blessed = {}       # pid -> atk_bonus
        self.taunted = None     # pid who has taunt active
        self.chests  = {}       # chest_id -> chest dict (persistent world loot)
        self.ground_items = {}  # gid -> {"id","item","pos":[x,y]} â€” itens largados no chÃ£o (persistem como chests)
        self.shop_scrolls = []  # pergaminhos Ã  venda no mercador (renovados por visita Ã  cidade)
        self.decorations = []
        self.secret_passages = []
        self._decor_block_tiles = set()
        self._decor_tall_tiles = set()
        self._campfire_tiles = set()
        self.materiais = {}            # {(x,y): material_id} â€” camada de piso/parede
        self._mat_solid_tiles = set()  # casas de material sÃ³lido (entulho) â€” bloqueia
        self._mat_oclui_tiles = set()  # casas de material opaco (entulho) â€” barra visÃ£o

    # â”€â”€ broadcast helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

    async def broadcast(self, msg):
        dead = []
        data = json.dumps(msg)
        for pid, ws in list(self.connections.items()):
            try:
                await ws.send(data)
            except Exception:
                dead.append(pid)
        for pid in dead:
            self.connections.pop(pid, None)

    async def send_to(self, pid, msg):
        ws = self.connections.get(pid)
        if ws:
            try:
                await ws.send(json.dumps(msg))
            except Exception:
                pass

    # Atraso por casa na animaÃ§Ã£o fiel de deslize (monstros inimigos e servos
    # auto-comandados). ~0.12s/casa: prÃ³ximo dos 0,25s/casa do herÃ³i, mas mais
    # Ã¡gil para nÃ£o arrastar o turno dos monstros. Ajuste aqui para mudar o ritmo.
    STEP_ANIM_DELAY = 0.12

    async def _emit_entity_step(self, entity_id, frm, to, kind):
        """Anima o deslize de UMA casa no cliente (kind: 'monster'|'animado').
        O cliente interpola fromâ†’to ao longo de STEP_ANIM_DELAY; o push_state
        seguinte reconcilia a posiÃ§Ã£o autoritativa final."""
        await self.broadcast({
            "type": "entity_step",
            "id": entity_id, "from": list(frm), "to": list(to), "kind": kind,
        })
        await asyncio.sleep(self.STEP_ANIM_DELAY)

    async def gm_say(self, text):
        self.gm_log.append(text)
        if len(self.gm_log) > 80:
            self.gm_log = self.gm_log[-60:]
        await self.broadcast({"type": "gm_narration", "text": text})

    # â”€â”€ lobby â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

    async def add_player(self, ws, pid, name):
        # Fase A: o mestre deve assumir o papel ANTES da sala encher com 6 herÃ³is
        # (ou um herÃ³i sentado troca para mestre, liberando um slot). Um 7Âº entrante
        # dedicado a mestre nÃ£o cabe numa sala jÃ¡ cheia de herÃ³is â€” limitaÃ§Ã£o aceita.
        heroes = sum(1 for p in self.players.values() if not p.get("is_master"))
        if heroes >= 6:
            await ws.send(json.dumps({"type": "error", "msg": "Sala cheia (mÃ¡ximo 6 herÃ³is)."}))
            return False
        self.connections[pid] = ws
        self.players[pid] = {"id": pid, "name": name, "class_id": None, "ready": False, "connected": True, "slot": len(self.players)}
        if not self.host_pid:
            self.host_pid = pid
        await self.broadcast_lobby()
        return True

    async def select_class(self, pid, cls_id):
        if self.players.get(pid, {}).get("is_master"):
            await self.send_to(pid, {"type": "error",
                "msg": "O mestre nÃ£o escolhe classe. Solte o papel de mestre primeiro."})
            return
        if cls_id not in CLASSES:
            return
        # NÃ£o tomado na sala
        taken = [p["class_id"] for p in self.players.values() if p["id"] != pid]
        if cls_id in taken:
            await self.send_to(pid, {"type": "error", "msg": "Classe jÃ¡ escolhida por outro jogador."})
            return
        # Trava global: personagem em uso em OUTRA sala
        dono = CHARACTERS_IN_USE.get(cls_id)
        if dono and dono != self.code:
            await self.send_to(pid, {"type": "error",
                "msg": f"{CLASSES[cls_id]['name']} jÃ¡ estÃ¡ em uso em outra sala."})
            return
        # Libera o personagem anterior deste jogador (se trocou de classe)
        prev = self.players[pid].get("class_id")
        if prev and prev != cls_id and CHARACTERS_IN_USE.get(prev) == self.code:
            del CHARACTERS_IN_USE[prev]
        CHARACTERS_IN_USE[cls_id] = self.code
        self.players[pid]["class_id"] = cls_id
        self.players[pid]["ready"] = True
        await self.broadcast_lobby()

    async def claim_role(self, pid, role):
        """Lobby: um jogador assume ('master') ou solta ('hero') o papel de mestre."""
        if self.phase != "lobby":
            return
        p = self.players.get(pid)
        if not p:
            return
        if role not in ("master", "hero"):
            return
        if role == "master":
            outro = next((q for q in self.players.values()
                          if q.get("is_master") and q["id"] != pid), None)
            if outro:
                await self.send_to(pid, {"type": "error",
                    "msg": "JÃ¡ existe um mestre nesta sala."})
                return
            prev = p.get("class_id")
            if prev and CHARACTERS_IN_USE.get(prev) == self.code:
                del CHARACTERS_IN_USE[prev]
            p["is_master"] = True
            p["class_id"] = None
            p["ready"] = True
            self.master_pid = pid
            self.master_name = p["name"]
        else:  # "hero"
            if not p.get("is_master"):
                return
            p["is_master"] = False
            p["ready"] = False
            if self.master_pid == pid:
                self.master_pid = None
                self.master_name = None
        await self.broadcast_lobby()

    async def handle_set_known_spells(self, pid, ids):
        """Lobby: mago/clÃ©rigo escolhe 2 magias de 1Âº cÃ­rculo da prÃ³pria classe."""
        p = self.players.get(pid)
        if not p or self.phase != "lobby":
            return
        if p.get("class_id") not in ("mage", "cleric"):
            await self.send_to(pid, {"type": "error", "msg": "Sua classe nÃ£o escolhe magias."}); return
        ids = list(dict.fromkeys(ids or []))   # remove duplicatas, preserva ordem
        if len(ids) != 2:
            await self.send_to(pid, {"type": "error", "msg": "Escolha exatamente 2 magias de 1Âº cÃ­rculo."}); return
        for mid in ids:
            m = GRIMORIO.get(mid)
            if not m or p["class_id"] not in m.get("classe", []) or m.get("circulo") != "primeiro":
                await self.send_to(pid, {"type": "error", "msg": "Magia invÃ¡lida para sua classe/cÃ­rculo."}); return
        p["magias_conhecidas"] = ids
        await self.broadcast_lobby()

    async def handle_escolher_magia_nivel(self, pid, magia_id):
        """Resolve a escolha de nova magia pendente (1 item da fila por vez)."""
        p = self.players.get(pid)
        if not p:
            return
        fila = p.get("pending_spell_pick") or []
        if not fila:
            await self.send_to(pid, {"type": "error", "msg": "Nenhuma escolha de magia pendente."}); return
        circ = fila[0]
        m = GRIMORIO.get(magia_id)
        if not m or p["class_id"] not in m.get("classe", []) or m.get("circulo") != circ:
            await self.send_to(pid, {"type": "error", "msg": "Magia invÃ¡lida para este cÃ­rculo/classe."}); return
        if magia_id in p.get("magias_conhecidas", []):
            await self.send_to(pid, {"type": "error", "msg": "VocÃª jÃ¡ conhece essa magia."}); return
        p.setdefault("magias_conhecidas", []).append(magia_id)
        fila.pop(0)
        await self.gm_say(f"ðŸ“– **{p['name']}** aprendeu **{m['nome']}**!")
        if fila:
            await self._enviar_spell_pick_prompt(p)   # prÃ³xima da fila
        await self.push_state()

    def _can_start(self):
        heroes = [p for p in self.players.values() if not p.get("is_master")]
        return len(heroes) >= 1 and all(p["class_id"] for p in heroes)

    async def broadcast_lobby(self):
        await self.broadcast({
            "type": "lobby_state",
            "code": self.code,
            "host": self.host_pid,
            "players": list(self.players.values()),
            "classes": {k: {"name": v["name"], "emoji": v["emoji"], "color": v["color"], "desc": v["desc"]} for k, v in CLASSES.items()},
            "can_start": self._can_start(),
            "master_pid": self.master_pid,
            "dungeons": listar_dungeons(),
            "campaigns": listar_campanhas(),
            "mode": self.mode,
            "selected_dungeon": self.selected_dungeon,
            "selected_campaign": self.selected_campaign,
        })

    async def handle_select_dungeon(self, pid, file):
        """Host escolhe a masmorra do lobby. file=None â†’ procedural."""
        if pid != self.host_pid:
            return
        if self.phase != "lobby":
            return
        if not file:
            self.mode = "procedural"; self.selected_dungeon = None
            self.dungeon_def = None
            self.campaign = None; self.campaign_phase = 0; self.selected_campaign = None
        else:
            defn = carregar_dungeon(file)
            ok, msg = (False, "Masmorra nÃ£o encontrada.") if defn is None else validar_dungeon(defn)
            if not ok:
                await self.send_to(pid, {"type": "error", "msg": f"Masmorra invÃ¡lida: {msg}"})
                return
            # Guarda o dict jÃ¡ carregado/validado para enter_dungeon usar
            # (autorada = mode=="authored" and self.dungeon_def is not None).
            self.mode = "authored"; self.selected_dungeon = file
            self.dungeon_def = defn
            self.campaign = None; self.campaign_phase = 0; self.selected_campaign = None
        await self.broadcast_lobby()

    async def handle_select_campaign(self, pid, file):
        """Host escolhe uma campanha do lobby. file=None â†’ procedural."""
        if pid != self.host_pid:
            return
        if self.phase != "lobby":
            return
        if not file:
            self.mode = "procedural"; self.selected_dungeon = None
            self.dungeon_def = None; self.campaign = None; self.campaign_phase = 0; self.selected_campaign = None
        else:
            defn = carregar_campanha(file)
            ok, msg = (False, "Campanha nÃ£o encontrada.") if defn is None else validar_campanha(defn)
            if not ok:
                await self.send_to(pid, {"type": "error", "msg": f"Campanha invÃ¡lida: {msg}"})
                return
            self.mode = "campaign"; self.campaign = defn; self.campaign_phase = 0
            self.selected_campaign = file
            self.selected_dungeon = None; self.dungeon_def = None
        await self.broadcast_lobby()

    # â”€â”€ game start â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

    async def start_game(self, pid):
        if pid != self.host_pid:
            await self.send_to(pid, {"type": "error", "msg": "Apenas o anfitriÃ£o pode iniciar."})
            return
        heroes = {pid2: p for pid2, p in self.players.items() if not p.get("is_master")}
        master_entry = next((p for p in self.players.values() if p.get("is_master")), None)
        if not heroes:
            await self.send_to(pid, {"type": "error", "msg": "Ã‰ preciso pelo menos 1 herÃ³i para iniciar."})
            return
        if not all(p["class_id"] for p in heroes.values()):
            await self.send_to(pid, {"type": "error", "msg": "Todos os herÃ³is devem escolher uma classe."})
            return
        for pp in heroes.values():
            if pp["class_id"] in ("mage", "cleric") and len(pp.get("magias_conhecidas", [])) < 2:
                await self.send_to(pid, {"type": "error",
                    "msg": "Magos e clÃ©rigos devem escolher 2 magias antes de iniciar."}); return

        # Build full player states â€” SOMENTE herÃ³is; o mestre nÃ£o vira peÃ£o.
        full_players = {}
        for slot, (pid2, p) in enumerate(heroes.items()):
            novo = make_player(pid2, p["name"], p["class_id"], slot)
            novo["magias_conhecidas"] = list(p.get("magias_conhecidas", []))
            apply_guild_save(novo)   # carrega compras/equip persistidos do personagem
            full_players[pid2] = novo
        self.players = full_players
        self.player_order = list(full_players.keys())
        if master_entry:
            self.master_pid = master_entry["id"]
            self.master_name = master_entry["name"]

        # Transition to city phase so players can shop before the dungeon
        self.phase = "city"
        self._gerar_loja_pergaminhos()
        await self.broadcast({"type": "game_start", "instrumentos_base": INSTRUMENTOS_BASE})
        await self.broadcast_city_state()

    # â”€â”€ city phase â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

    async def broadcast_city_state(self):
        await self.broadcast({
            "type": "city_state",
            "master_pid": self.master_pid,
            "players": list(self.players.values()),
            "host": self.host_pid,
            "campaign": self._campaign_payload(),
            "shops": {
                "ferreiro": {"weapons": SHOP_WEAPONS, "armors": SHOP_ARMORS, "ammo": SHOP_AMMO},
                "mercador": SHOP_MERCHANT + self.shop_scrolls,   # mercador inclui pergaminhos
                "templo":   SHOP_TEMPLE,
                "taverna":  SHOP_TAVERN,
            },
            "guild": {
                "catalog": list(GUILD_CATALOG.values()),
                "players": {
                    pid: {"owned": pp["guild_owned"], "equip": pp["guild_equip"]}
                    for pid, pp in self.players.items()
                },
            },
        })

    def _gerar_loja_pergaminhos(self):
        """Renova o estoque de pergaminhos do mercador: uma MISTURA de bÃ¡sicos
        (nÃ­vel mÃ­nimo, +0 INT) e reforÃ§ados (nÃ­vel de conjurador e/ou INT maiores,
        com preÃ§o calculado). Ids Ãºnicos p/ a compra."""
        def _tal():
            # Pede os 3 talentos com ~40% cada; gerar_pergaminho filtra os aplicÃ¡veis.
            return {"cd": random.random() < 0.4, "duracao": random.random() < 0.4,
                    "dano": random.random() < 0.4}
        specs = [
            (1, None, 0, None),                                      # 1Âº bÃ¡sico
            (1, None, 0, None),                                      # 1Âº bÃ¡sico
            (1, random.randint(2, 5), random.randint(0, 2), _tal()), # 1Âº reforÃ§ado
            (2, None, 0, None),                                      # 2Âº bÃ¡sico
            (2, random.randint(3, 5), random.randint(0, 3), _tal()), # 2Âº reforÃ§ado
            (3, None, random.randint(0, 2), _tal()),                # 3Âº reforÃ§ado
        ]
        ofertas = []
        for i, (circ, nivel, intb, tal) in enumerate(specs):
            sc = gerar_pergaminho(circ, nivel=nivel, int_bonus=intb, talentos=tal)
            if not sc:
                continue
            sc["id"] = f"{sc['id']}_loja{i}"   # id Ãºnico p/ a compra
            ofertas.append(sc)
        self.shop_scrolls = ofertas

    async def handle_guild_buy(self, pid, item_id):
        """Compra uma tÃ©cnica/especializaÃ§Ã£o da Guilda dos HerÃ³is (persistente por classe)."""
        if self.phase != "city":
            return
        p = self.players.get(pid)
        if not p:
            return
        item = guild_item(item_id)
        if not item:
            await self.send_to(pid, {"type": "error", "msg": "Item da guilda desconhecido."})
            return
        # Classe compatÃ­vel (classe pode ser None, 1 class_id, ou lista de class_ids)
        if not _guild_classe_ok(item["classe"], p.get("class_id")):
            await self.send_to(pid, {"type": "error", "msg": "Este aprimoramento nÃ£o Ã© da sua classe."})
            return
        cat = item["categoria"]   # "tecnica" | "especializacao"
        owned = p["guild_owned"]["tecnicas"] if cat == "tecnica" else p["guild_owned"]["especializacoes"]
        if item_id in owned:
            await self.send_to(pid, {"type": "error", "msg": "VocÃª jÃ¡ possui isto."})
            return
        # PrÃ©-requisito
        req = item.get("requer")
        if req and req not in owned:
            nome_req = (guild_item(req) or {}).get("nome", req)
            await self.send_to(pid, {"type": "error", "msg": f"Requer antes: {nome_req}."})
            return
        # Ouro
        if p.get("gold", 0) < item["preco"]:
            await self.send_to(pid, {"type": "error", "msg": "Ouro insuficiente."})
            return
        p["gold"] -= item["preco"]
        owned.append(item_id)
        write_guild_save(p)
        await self.broadcast_city_state()

    async def handle_guild_equip(self, pid, slot, item_id):
        """Equipa (ou desequipa, item_id=None) uma tÃ©cnica da Guilda num slot.
        'tecnica' Ã© genÃ©rico (todas as classes); 'tecnica_exclusiva' sÃ³ mago/clÃ©rigo
        e sÃ³ aceita item com exclusiva=True."""
        if self.phase != "city":
            await self.send_to(pid, {"type": "error", "msg": "SÃ³ Ã© possÃ­vel equipar tÃ©cnicas na cidade."})
            return
        p = self.players.get(pid)
        if not p:
            return
        if slot not in ("tecnica", "tecnica_exclusiva"):
            await self.send_to(pid, {"type": "error", "msg": "Slot de tÃ©cnica invÃ¡lido."})
            return
        # Slot exclusivo sÃ³ para mago/clÃ©rigo
        if slot == "tecnica_exclusiva" and p.get("class_id") not in ("mage", "cleric"):
            await self.send_to(pid, {"type": "error", "msg": "Sua classe nÃ£o tem slot de tÃ©cnica exclusiva."})
            return
        if item_id is None:   # desequipar
            p["guild_equip"][slot] = None
            write_guild_save(p)
            await self.broadcast_city_state()
            return
        item = guild_item(item_id)
        if not item or item["categoria"] != "tecnica":
            await self.send_to(pid, {"type": "error", "msg": "TÃ©cnica desconhecida."})
            return
        if item_id not in p["guild_owned"]["tecnicas"]:
            await self.send_to(pid, {"type": "error", "msg": "VocÃª nÃ£o possui esta tÃ©cnica."})
            return
        # CoerÃªncia exclusiva â†” slot
        if slot == "tecnica_exclusiva" and not item.get("exclusiva"):
            await self.send_to(pid, {"type": "error", "msg": "Esta tÃ©cnica nÃ£o Ã© exclusiva."})
            return
        if slot == "tecnica" and item.get("exclusiva"):
            await self.send_to(pid, {"type": "error", "msg": "TÃ©cnica exclusiva vai no slot exclusivo."})
            return
        p["guild_equip"][slot] = item_id
        write_guild_save(p)
        await self.broadcast_city_state()

    # â”€â”€ Guilda dos HerÃ³is: usar tÃ©cnica na masmorra â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    def tecnica_restante(self, p, tid):
        """Rodadas restantes de recarga de uma tÃ©cnica (0 se pronta)."""
        pronta = p.get("technique_cooldowns", {}).get(tid)
        return max(0, pronta - self.round_num) if pronta else 0

    def _tecnica_bonus_dano(self, p):
        """+N de dano de arma concedido por tÃ©cnica de turno (Brutalidade)."""
        return p.get("tecnica_buff_dano_arma", 0)

    def _pressao_ca_pen(self, m):
        """-CA da PressÃ£o Constante enquanto ativa no monstro."""
        return m.get("pressao_ca_val", 0) if m.get("pressao_ca_ate", 0) >= self.round_num else 0

    def _acorde_atk_pen(self, m):
        """-1 de Ataque do Tambor RÃºnico (sucesso no save), atÃ© o prÃ³ximo turno do monstro."""
        return -1 if m.get("acorde_atk_pen_ate", 0) >= self.round_num else 0

    def _defesa_impecavel_ativa(self, p):
        """True enquanto a janela da Defesa ImpecÃ¡vel estiver ativa (atÃ© o prÃ³ximo turno)."""
        return p.get("defesa_impecavel_ate", 0) >= self.round_num

    def _passo_fantasma_ativo(self, p):
        """True enquanto a janela do Passo Fantasma estiver ativa (1d4 rodadas)."""
        return p.get("passo_fantasma_ate", 0) >= self.round_num

    def _furia_extras(self, p):
        """Ataques extras concedidos pela FÃºria: 2 com NÃ­vel III, senÃ£o 1."""
        return 2 if tem_espec(p, "guerreiro_furia_3") else 1

    def _mira_dano_bonus(self, p):
        """+2 de dano da Mira Certeira III (0 se nÃ£o possuÃ­do)."""
        return 2 if tem_espec(p, "guerreiro_mira_3") else 0

    def _teto_combinacao(self, p):
        """MÃ¡x. de habilidades do warrior armadas por turno pela posse de especializaÃ§Ãµes."""
        if tem_espec(p, "guerreiro_mestre_combate"): return 3
        if tem_espec(p, "guerreiro_combinar_2"):      return 2
        return 1

    def _teto_metamagia(self, p):
        """Quantas metamagias podem empilhar no mesmo lanÃ§amento (base 1)."""
        if tem_espec(p, "mago_tecelagem_3"): return 3
        if tem_espec(p, "mago_tecelagem_2"): return 2
        return 1

    def _fortalecer_mult(self, p):
        """Multiplicador de dano do Fortalecer Magia (base Ã—1,25)."""
        if tem_espec(p, "mago_fortalecer_3"): return 2.0
        if tem_espec(p, "mago_fortalecer_2"): return 1.5
        return 1.25

    def _aprimorar_bonus(self, p):
        """BÃ´nus na CD do save do Aprimorar Magia (base +1)."""
        if tem_espec(p, "mago_aprimorar_3"): return 3
        if tem_espec(p, "mago_aprimorar_2"): return 2
        return 1

    def _estender_bonus(self, p):
        """Rodadas extras de duraÃ§Ã£o do Estender Magia (base +1)."""
        if tem_espec(p, "mago_estender_3"): return 3
        if tem_espec(p, "mago_estender_2"): return 2
        return 1

    def _reviver_nivel(self, p):
        """NÃ­vel de Reviver os Mortos possuÃ­do (1/2/3)."""
        if tem_espec(p, "mago_reviver_3"): return 3
        if tem_espec(p, "mago_reviver_2"): return 2
        return 1

    def _reviver_slots_max(self, p):
        """Slots de Controle totais: mod(INT) + nÃ­vel_PedroÃ·2 (mÃ­n. 1), +2 no NÃ­vel III."""
        bonus_int = mod(p.get("int_", 10))
        base = max(1, bonus_int + p.get("level", 1) // 2)
        return base + 2 if self._reviver_nivel(p) == 3 else base

    def _reviver_slot_custo(self, p, nd):
        """Slots ocupados por uma criatura de ND `nd` (fracionÃ¡rio): 1 fixo no
        NÃ­vel I; exatamente `nd` (mÃ­n. proporcional) nos NÃ­veis II/III."""
        return 1 if self._reviver_nivel(p) == 1 else max(0.25, nd)

    def _reviver_chance(self, p, nd):
        """Chance de sucesso (%) para animar uma criatura de ND `nd`. Soma um
        bÃ´nus de +5% por nÃ­vel de Pedro (nivel_Pedro Ã— 5) antes do teto/piso."""
        nivel = self._reviver_nivel(p)
        reducao = {1: 20, 2: 15, 3: 10}[nivel]
        bonus_nivel = p.get("level", 1) * 5
        return min(99, max(1, round(100 - nd * reducao + bonus_nivel)))

    def _resolver_metamagia(self, p, magia):
        """Resolve as metamagias armadas aplicÃ¡veis a `magia`, respeitando o teto de
        empilhamento (ordem de prioridade: Fortalecer > Estender > Aprimorar).
        Retorna (dmg_mult, dur_bonus, dc_bonus, mm_fome, mm_sede, partes, excedeu)."""
        dmg_mult, dur_bonus, dc_bonus = 1, 0, 0
        tem_dano    = self._magia_tem_dano(magia)
        tem_duracao = "duracao" in magia
        tem_save    = "save" in magia
        candidatas = []   # (kind, custo_fome, custo_sede) â€” armadas E aplicÃ¡veis
        if p.get("fortalecer_ativo") and tem_dano:    candidatas.append(("fortalecer", 6, 6))
        if p.get("estender_ativo") and tem_duracao:   candidatas.append(("estender", 3, 3))
        if p.get("aprimorar_ativo") and tem_save:     candidatas.append(("aprimorar", 3, 0))
        teto = self._teto_metamagia(p)
        aplicadas = candidatas[:teto]
        mm_fome = mm_sede = 0
        partes = []
        for kind, cf, cs in aplicadas:
            if kind == "fortalecer":
                dmg_mult = self._fortalecer_mult(p); mm_fome += cf; mm_sede += cs
                partes.append(f"Fortalecer (dano Ã—{f'{dmg_mult:g}'.replace('.', ',')})")
            elif kind == "estender":
                dur_bonus = self._estender_bonus(p); mm_fome += cf; mm_sede += cs
                partes.append(f"Estender (+{dur_bonus} turno{'s' if dur_bonus != 1 else ''})")
            elif kind == "aprimorar":
                dc_bonus = self._aprimorar_bonus(p); mm_fome += cf; mm_sede += cs
                partes.append(f"Aprimorar (+{dc_bonus} CD)")
        return dmg_mult, dur_bonus, dc_bonus, mm_fome, mm_sede, partes, (len(candidatas) > teto)

    # â”€â”€ TÃ©cnicas Exclusivas da Guilda (Fase 3, Mago/ClÃ©rigo) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # Independentes da Metamagia acima: helpers puros lidos em handle_magia; os
    # bÃ´nus se SOMAM (dc/duraÃ§Ã£o/alcance) ou multiplicam em cadeia (dano) com a
    # Metamagia do Mago, se ambas estiverem ativas no mesmo lanÃ§amento.
    def _tec_ex_dc_bonus(self, p, magia):
        """+1 na CD do save se Aprimorar Magia (Fase 3) estiver armada e a magia
        exigir teste de resistÃªncia."""
        return 1 if (p.get("tec_ex_aprimorar_armado") and "save" in magia) else 0

    def _tec_ex_dur_alcance_bonus(self, p, magia):
        """(dur_bonus, alcance_bonus) de Estender Magia (Fase 3): +1 rodada de
        duraÃ§Ã£o se a magia tiver 'duracao', senÃ£o +1 quadrado de alcance."""
        if not p.get("tec_ex_estender_armado"):
            return 0, 0
        return (1, 0) if "duracao" in magia else (0, 1)

    def _tec_ex_dmg_mult(self, p, magia):
        """Ã—1,5 de Empoderar Magia (Fase 3) se a magia causar dano."""
        return 1.5 if (p.get("tec_ex_empoderar_armado") and self._magia_tem_dano(magia)) else 1

    def _geminada_alvo2_valido(self, caster, magia, alvo2):
        """True se o 2Âº alvo da Magia Geminada Ã© elegÃ­vel: vivo, no alcance da
        magia a partir do caster, e do tipo certo (monstro p/ magia ofensiva
        'alvo', aliado p/ magia de buff 'alvo_aliado'/'buff_aliado')."""
        if not alvo2:
            return False
        vivo = alvo2["alive"] if self._eh_jogador(alvo2) else alvo2.get("hp", 0) > 0
        if not vivo:
            return False
        tipo = magia.get("tipo")
        if tipo == "alvo" and self._eh_jogador(alvo2):
            return False
        if tipo in ("alvo_aliado", "buff_aliado") and not self._eh_jogador(alvo2):
            return False
        alcance = magia.get("alcance")
        if alcance is None:
            nivel = caster.get("level", 1)
            alcance = magia.get("alcance_base", 0) + magia.get("alcance_escala", 0) * (nivel - 1)
        dist = max(abs(caster["pos"][0] - alvo2["pos"][0]), abs(caster["pos"][1] - alvo2["pos"][1]))
        return dist <= alcance

    def _golpe_raw(self, p, raw):
        """Golpe Devastador nos dados: Ã—2 com NÃ­vel III, Ã—1,5 (floor) no base; sem efeito se nÃ£o armado."""
        if not p.get("skill_dobrar_dano"):
            return raw
        if tem_espec(p, "guerreiro_golpe_3"):
            return raw * 2
        return raw + raw // 2

    def _cura_teto(self, p):
        """MÃ¡x. de d8 da Cura pela posse (1 base / 2 / 3)."""
        if tem_espec(p, "clerigo_cura_3"): return 3
        if tem_espec(p, "clerigo_cura_2"): return 2
        return 1

    def _massa_nivel(self, p):
        """NÃ­vel da Cura em Massa (1/2/3) â€” define teto de dados E raio (2Ã—nÃ­vel)."""
        if tem_espec(p, "clerigo_massa_3"): return 3
        if tem_espec(p, "clerigo_massa_2"): return 2
        return 1

    def _purif_tipos(self, p):
        """Tipos de purificaÃ§Ã£o destravados pela posse."""
        tipos = {"veneno"}
        if tem_espec(p, "clerigo_purif_2"): tipos.add("doenca")
        if tem_espec(p, "clerigo_purif_3"): tipos |= {"maldicao", "petrificacao"}
        return tipos

    def _ressur_nivel(self, p):
        """NÃ­vel da RessurreiÃ§Ã£o (1/2/3) pela posse."""
        if tem_espec(p, "clerigo_ressur_3"): return 3
        if tem_espec(p, "clerigo_ressur_2"): return 2
        return 1

    def _cura_maos_dados(self, p):
        """Dados base da Cura pelas MÃ£os (1 base / 2 com paladino_cura_maos_2)."""
        return 2 if tem_espec(p, "paladino_cura_maos_2") else 1

    def _ataque_sagrado_dados(self, p):
        """Dados do dano sagrado do Golpe Sagrado (1 base / 2 com paladino_ataque_sagrado_2)."""
        return 2 if tem_espec(p, "paladino_ataque_sagrado_2") else 1

    def _gdl_max_atributos(self, p):
        """MÃ¡x. de atributos simultÃ¢neos do Guerreiro da Luz (2 base / 3 / 4)."""
        if tem_espec(p, "paladino_luz_3"): return 4
        if tem_espec(p, "paladino_luz_2"): return 3
        return 2

    def _gdl_trap_raio(self, p):
        """Raio de detecÃ§Ã£o de armadilhas do Guerreiro da Luz (1 base / 2 / 3)."""
        if tem_espec(p, "paladino_luz_3"): return 3
        if tem_espec(p, "paladino_luz_2"): return 2
        return 1

    def _defensor_raio(self, p):
        """Alcance do Protetor (4 base / 5 com paladino_defensor_2)."""
        return 5 if tem_espec(p, "paladino_defensor_2") else 4

    def _defensor_split(self, richard, dano):
        """DivisÃ£o do dano do Protetor: 50/50 base; 40/40 (20% mitigado) com paladino_defensor_3."""
        if tem_espec(richard, "paladino_defensor_3"):
            parte = (dano * 2) // 5   # 40% (floor); 20% mitigado
            return parte, parte
        metade = dano // 2
        return metade, metade

    def _regen_raio(self, p):
        """Raio de cura de aliados da RegeneraÃ§Ã£o Divina (0 base / 1 / 2)."""
        if tem_espec(p, "paladino_regen_3"): return 2
        if tem_espec(p, "paladino_regen_2"): return 1
        return 0

    def _resistencia_saves_bonus(self, p):
        """+N em todos os testes de resistÃªncia (TÃ©cnica ResistÃªncia Absoluta) enquanto vÃ¡lido nesta rodada."""
        return p.get("resistencia_saves_val", 0) if p.get("resistencia_saves_ate", 0) >= self.round_num else 0

    def _sangue_frio_consumir(self, p):
        """Consome a re-rolagem do Sangue Frio se armada. Retorna True se deve re-rolar."""
        if p.get("sangue_frio_armado"):
            p["sangue_frio_armado"] = False
            return True
        return False

    def _resolver_dano_ataque_basico(self, p, target, crit, roll, forca_critico=False,
                                       surv_mod=0, cancao_dano=0, gl_dano=0, bonus_extra=0,
                                       target_pos=None):
        """Rola e computa o dano fÃ­sico de um ataque bÃ¡sico (arma ou desarmado)
        que JÃ acertou â€” reaproveitado pelo hit normal de handle_attack e pelo
        reroll da Sorte. `forca_critico` Ã© quem decide se um natural 20 triplica
        (Golpe Decisivo/Ãšltimo EsforÃ§o) em vez de dobrar. `bonus_extra` cobre os
        bÃ´nus condicionais que sÃ³ se aplicam ao ataque ARMADO no site original
        (Mira Perfeita/Investida Heroica) â€” preservado apenas no ramo armado,
        fiel ao comportamento prÃ©-refactor. Retorna
        (dmg, weapon_name, dmg_detail, raw_dmg, die_str) â€” raw_dmg/die_str sÃ£o
        None no ataque desarmado (sem dado de arma), e nesse caso o cÃ¡lculo
        NÃƒO inclui skill_bonus_dano/corrosÃ£o/_apply_damage_types â€” exatamente
        como o bloco `else` original (ataque desarmado nunca teve esses termos).
        NÃ£o repete muniÃ§Ã£o/veneno/furtivo/projÃ©til incendiÃ¡rio â€” resolvidos Ã 
        parte pelo chamador."""
        weapon = p.get("weapon")
        die_str = weapon.get("die") if weapon else None
        if die_str:
            raw_dmg = roll_dice(die_str)
            raw_dmg = self._golpe_raw(p, raw_dmg)
            if weapon.get("finesse"):
                stat_bonus = max(mod(p.get("str_", 12)), mod(p.get("dex", 12)))
            else:
                stat_bonus = mod(p.get(weapon["stat"], 12))
            dmg = raw_dmg + stat_bonus
            if crit:
                dmg *= 3 if (forca_critico and roll == 20) else 2
            dmg = max(1, dmg + surv_mod + cancao_dano + gl_dano
                      + self._mod_magia(p, "dano") + self._tecnica_bonus_dano(p)
                      + bonus_extra + weapon.get("dmg_bonus", 0)
                      + p.get("skill_bonus_dano", 0) - self._corrosao_arma_pen(p))
            dmg = self._apply_damage_types(dmg, [DMG_PHYSICAL], target, weapon, p.get("pos"), target_pos)
            weapon_name = weapon.get("name", "arma")
            sb = f"+{stat_bonus}" if stat_bonus >= 0 else str(stat_bonus)
            dmg_detail = f"[{die_str}={raw_dmg}{sb}]"
        else:
            raw_dmg = None
            str_bonus = mod(p.get("str_", 12))
            base = 2 if p.get("skill_dobrar_dano") else 1
            dmg = base + str_bonus
            if crit:
                dmg *= 3 if (forca_critico and roll == 20) else 2
            dmg = max(1, dmg + surv_mod + cancao_dano + gl_dano + self._mod_magia(p, "dano")
                      + self._tecnica_bonus_dano(p))
            dmg = self._apply_damage_types(dmg, [DMG_PHYSICAL], target, None, p.get("pos"), target_pos)
            weapon_name = "soco"
            sb = f"+{str_bonus}" if str_bonus >= 0 else str(str_bonus)
            dmg_detail = f"[{base}{sb}]"
        return dmg, weapon_name, dmg_detail, raw_dmg, die_str

    async def handle_usar_tecnica(self, pid, tecnica_id, target_id=None):
        """Ativa uma tÃ©cnica equipada da Guilda (aÃ§Ã£o no turno do herÃ³i, incluindo
        a janela do Ãšltimo EsforÃ§o â€” mesma checagem de `_is_turn` usada pelos
        demais handlers de aÃ§Ã£o)."""
        if self.phase != "playing":
            return
        p = self.players.get(pid)
        if not p or not self._is_turn(pid):
            await self.send_to(pid, {"type": "error", "msg": "NÃ£o Ã© o seu turno."})
            return
        eq = p["guild_equip"]
        if tecnica_id not in (eq.get("tecnica"), eq.get("tecnica_exclusiva")):
            await self.send_to(pid, {"type": "error", "msg": "TÃ©cnica nÃ£o equipada."})
            return
        item = guild_item(tecnica_id)
        if not item:
            return
        if item.get("automatica"):
            await self.send_to(pid, {"type": "error",
                "msg": f"{item['nome']} Ã© automÃ¡tica â€” nÃ£o pode ser ativada manualmente."})
            return
        if self.tecnica_restante(p, tecnica_id) > 0:
            await self.send_to(pid, {"type": "error",
                "msg": f"{item['nome']} em recarga ({self.tecnica_restante(p, tecnica_id)} rodadas)."})
            return
        _ef, _es = self._custo_fome_sede_efetivo(p, item["custo_fome"], item["custo_sede"])
        if p.get("fome", 0) < _ef or p.get("sede", 0) < _es:
            await self.send_to(pid, {"type": "error", "msg": "Fome/sede insuficientes."})
            return
        ef = item.get("efeito", {})
        if ef.get("tipo") == "buff_turno":
            p["tecnica_buff_dano_arma"] = p.get("tecnica_buff_dano_arma", 0) + ef.get("bonus_dano_arma", 0)
        elif ef.get("tipo") == "mov_self_dobrar":
            p["moves_left"] = p.get("moves_left", 0) + p.get("spd", 0)
        elif ef.get("tipo") == "buff_aliados_mov":
            b = ef.get("bonus_mov", 2)
            for q in self.players.values():
                if not q.get("alive"): continue
                q["moves_left"] = q.get("moves_left", 0) + b
                q["mov_bonus_ate"] = self.round_num + 1
                q["mov_bonus_val"] = b
        elif ef.get("tipo") == "remove_status":
            # Medo, Atordoamento (perde_turno) e LentidÃ£o (status "lento": perde
            # metade dos turnos). O campo do status Ã© "lento", nÃ£o "lentidao"
            # (esse Ã© sÃ³ o id da magia no GRIMORIO).
            for k in ("com_medo", "medo_rodadas", "perde_turno",
                      "lento", "lento_rodadas", "lento_pulou"):
                p.pop(k, None)
            p["imune_silencio_ate"] = self.round_num + 1
        elif ef.get("tipo") == "mira_perfeita":
            p["tecnica_mira_perfeita"] = True
        elif ef.get("tipo") == "debuff_ca_alvo":
            alvo = self.monsters.get(target_id) if target_id else None
            if not alvo or alvo.get("hp", 0) <= 0:
                await self.send_to(pid, {"type": "error", "msg": "Alvo invÃ¡lido."}); return
            if max(abs(alvo["pos"][0]-p["pos"][0]), abs(alvo["pos"][1]-p["pos"][1])) > 1:
                await self.send_to(pid, {"type": "error", "msg": "O inimigo precisa estar adjacente."}); return
            alvo["pressao_ca_val"] = ef.get("ca", 2)
            alvo["pressao_ca_ate"] = self.round_num + ef.get("rodadas", 2)
        elif ef.get("tipo") == "defesa_impecavel":
            p["defesa_impecavel_ate"] = self.round_num + 1
        elif ef.get("tipo") == "tatica_defensiva":
            alvo = self.players.get(target_id) if target_id else None
            if not alvo or not alvo.get("alive") or alvo["id"] == pid:
                await self.send_to(pid, {"type": "error", "msg": "Escolha um aliado vivo."}); return
            if not self._no_raio(p, alvo, ef.get("raio", 4)):
                await self.send_to(pid, {"type": "error", "msg": "Aliado fora do alcance (4 casas)."}); return
            p["tatica_alvo"] = alvo["id"]
            p["tatica_ate"] = self.round_num + roll_dice("1d4")
        elif ef.get("tipo") == "passo_fantasma":
            p["passo_fantasma_ate"] = self.round_num + roll_dice("1d4")
            b = ef.get("bonus_mov", 2)
            p["moves_left"] = p.get("moves_left", 0) + b
            p["mov_bonus_ate"] = self.round_num + 1
            p["mov_bonus_val"] = b
        elif ef.get("tipo") == "investida":
            p["moves_left"] = p.get("moves_left", 0) + p.get("spd", 0)
            p["investida_origem"] = list(p["pos"])
            p["investida_armada"] = True
        elif ef.get("tipo") == "buff_saves":
            p["resistencia_saves_ate"] = self.round_num + ef.get("rodadas", 2)
            p["resistencia_saves_val"] = ef.get("saves", 2)
        elif ef.get("tipo") == "sangue_frio":
            p["sangue_frio_armado"] = True
        elif ef.get("tipo") == "ataque_coordenado":
            alvo = self.players.get(target_id) if target_id else None
            if not alvo or not alvo.get("alive") or alvo["id"] == pid:
                await self.send_to(pid, {"type": "error", "msg": "Escolha um aliado vivo."}); return
            p["coordenado_alvo"] = alvo["id"]
            p["coordenado_turno"] = self.turn_index
        elif ef.get("tipo") == "contra_ataque":
            p["contra_ataque_ate"] = self.round_num + 1
        elif ef.get("tipo") == "oportunidade":
            alvo = self.players.get(target_id) if target_id else None
            if not alvo or not alvo.get("alive") or alvo["id"] == pid:
                await self.send_to(pid, {"type": "error",
                    "msg": "Escolha um aliado vivo (nÃ£o pode ser vocÃª)."}); return
            alvo["oportunidade_credito"] = True
            alvo["oportunidade_round"] = self.round_num
        elif ef.get("tipo") == "golpe_decisivo":
            p["tecnica_golpe_decisivo_armado"] = True
        elif ef.get("tipo") == "sorte":
            perdido = p.get("ultimo_ataque_perdido")
            if not perdido:
                await self.send_to(pid, {"type": "error", "msg": "Nenhum ataque recente para rerolar."})
                return
            alvo = self.monsters.get(perdido["target_id"])
            if not alvo or alvo.get("hp", 0) <= 0:
                await self.send_to(pid, {"type": "error", "msg": "O alvo nÃ£o estÃ¡ mais disponÃ­vel."})
                return
            hit, roll, total, crit, _desc = self._rolar_ataque(
                perdido["eff_atk"], perdido["eff_target_ac"], perdido["vantagem"], perdido["desvantagem"])
            await self.broadcast({"type": "dice_roll", "die": "d20", "value": roll,
                                   "label": "ðŸŽ² Sorte (nova rolagem)", "hit": hit, "crit": crit})
            if hit:
                # forca_critico deliberadamente OMITIDO: Sorte sÃ³ reproduz o d20/CA
                # congelados do ataque original, nunca deve ressuscitar uma flag de
                # crÃ­tico garantido (Golpe Decisivo/Ãšltimo EsforÃ§o) que jÃ¡ foi
                # consumida (ou nem estava armada) no momento do erro original.
                dmg, weapon_name, dmg_detail, raw_dmg, die_str = self._resolver_dano_ataque_basico(
                    p, alvo, crit, roll, surv_mod=perdido.get("surv_mod", 0),
                    cancao_dano=perdido.get("cancao_dano", 0), gl_dano=perdido.get("gl_dano", 0))
                alvo["hp"] -= dmg
                await self.gm_say(f"ðŸŽ² **{p['name']}** forÃ§a a Sorte e acerta **{alvo['name']}** com {weapon_name} {dmg_detail} = **{dmg}**!")
                if alvo["hp"] <= 0:
                    await self._monster_dies(alvo, pid)
            else:
                await self.gm_say(f"ðŸŽ² **{p['name']}** tenta a Sorte de novo, mas erra outra vez!")
            p["ultimo_ataque_perdido"] = None
        # â”€â”€ TÃ©cnicas Exclusivas da Guilda (Fase 3, Mago/ClÃ©rigo) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        elif ef.get("tipo") == "tec_ex_aprimorar":
            p["tec_ex_aprimorar_armado"] = True
        elif ef.get("tipo") == "tec_ex_estender":
            p["tec_ex_estender_armado"] = True
        elif ef.get("tipo") == "tec_ex_canalizacao_arcana":
            p["tec_ex_canalizacao_armado"] = True
        elif ef.get("tipo") == "tec_ex_empoderar":
            p["tec_ex_empoderar_armado"] = True
        elif ef.get("tipo") == "tec_ex_geminada":
            alvo2 = self.players.get(target_id) or self.monsters.get(target_id)
            vivo2 = alvo2 and (alvo2["alive"] if self._eh_jogador(alvo2) else alvo2.get("hp", 0) > 0)
            if not alvo2 or not vivo2 or target_id == pid:
                await self.send_to(pid, {"type": "error",
                    "msg": "Escolha um alvo vivo (nÃ£o pode ser vocÃª)."}); return
            p["tec_ex_geminada_alvo2_id"] = target_id
        elif ef.get("tipo") == "tec_ex_canalizacao_perfeita":
            p["tec_ex_canalizacao_perfeita_armado"] = True
        elif ef.get("tipo") == "tec_ex_acelerada":
            p["tec_ex_acelerada_armado"] = True
        # (outros tipos/handlers chegam nas Fases 1-2)
        self._pagar_fome_sede(p, item["custo_fome"], item["custo_sede"])
        p["technique_cooldowns"][tecnica_id] = self.round_num + item["recarga_rodadas"]
        await self.gm_say(f"âš”ï¸ **{p['name']}** ativa **{item['nome']}**!")
        await self.push_state()

    def _rolar_2d6(self):
        return random.randint(1, 6) + random.randint(1, 6)

    def _improviso_rolar_cascata(self, runico):
        """Resolve a cascata de Improviso. Devolve (passos, meta):
          passos: resultados 2-11 aplicaveis (12 nunca entra);
          meta: {'encore_menor': bool, 'grande_encore': bool}.
        12 = Encore -> rola +2x. O 2o 12 na cadeia liga encore_menor.
        So a Gaita Runica recursa em cada 12; o 3o 12 liga grande_encore."""
        passos = []
        meta = {"encore_menor": False, "grande_encore": False}
        contador = [0]
        TETO = 40

        def _encore():
            # um "12" acabou de sair: conta e rola +2x, processando cada resultado.
            contador[0] += 1
            if contador[0] >= 2:
                meta["encore_menor"] = True
            if contador[0] >= 3 and runico:
                meta["grande_encore"] = True
            for _ in range(2):
                if contador[0] > TETO:
                    break
                sub = self._rolar_2d6()
                if sub == 12:
                    if runico:
                        _encore()          # cada 12 gera seus proprios 2 rerolls
                    else:
                        contador[0] += 1   # nao-runica: conta o 12 (liga encore_menor) mas nao recursa
                        if contador[0] >= 2:
                            meta["encore_menor"] = True
                else:
                    passos.append(sub)

        r = self._rolar_2d6()
        if r == 12:
            _encore()
        else:
            passos.append(r)
        return passos, meta

    async def handle_usar_instrumento(self, pid, data=None):
        """Ativa a habilidade do instrumento equipado (bardo). Espelha
        handle_usar_tecnica: valida turno/economia de aÃ§Ã£o/custo ðŸ–ðŸ’§ e despacha
        por efeito.tipo. Passivas (AlaÃºde) nunca chegam aqui."""
        if self.phase != "playing":
            return
        p = self.players.get(pid)
        if not p or not p.get("alive") or not self._is_turn(pid):
            await self.send_to(pid, {"type": "error", "msg": "NÃ£o Ã© o seu turno."}); return
        if p.get("class_id") != "bard":
            await self.send_to(pid, {"type": "error", "msg": "Apenas o bardo usa instrumentos."}); return
        inst = p["gear"].get("off_hand")
        if not inst or inst.get("tipo_item") != "instrumento":
            await self.send_to(pid, {"type": "error", "msg": "Nenhum instrumento equipado (mÃ£o do escudo)."}); return
        base = INSTRUMENTOS_BASE[inst["base"]]
        if base["modo"] != "ativada":
            await self.send_to(pid, {"type": "error",
                "msg": f"{base['habilidade_nome']} Ã© passiva â€” nÃ£o precisa ativar."}); return
        # RÃ©quiem Final: clicar de novo com o RÃ©quiem ativo DESLIGA (grÃ¡tis, sempre disponÃ­vel).
        if base["efeito"]["tipo"] == "requiem_final" and p.get("requiem_alvo") \
           and not (data or {}).get("target_id"):
            await self._encerrar_requiem(p, "desativado manualmente")
            await self.push_state()
            return
        duas_maos = base["maos"] == 2
        if p.get("instrumento_usado"):
            await self.send_to(pid, {"type": "error",
                "msg": "VocÃª jÃ¡ tocou um instrumento neste turno."}); return
        if duas_maos and p.get("action_done"):
            await self.send_to(pid, {"type": "error",
                "msg": "Instrumento de 2 mÃ£os exige concentraÃ§Ã£o â€” vocÃª jÃ¡ usou sua aÃ§Ã£o."}); return
        st = self._instrumento_stats(inst)
        _ef, _es = self._custo_fome_sede_efetivo(p, st["custo_fome"], st["custo_sede"])
        if p.get("fome", 0) < _ef or p.get("sede", 0) < _es:
            await self.send_to(pid, {"type": "error", "msg": "Fome/sede insuficientes."}); return

        tipo = base["efeito"]["tipo"]
        ok = False
        if tipo == "nota_cortante":
            ok = await self._instr_nota_cortante(p, inst, st, data)
        elif tipo == "acorde_trovejante":
            ok = await self._instr_acorde_trovejante(p, inst, st, data)
        elif tipo == "ecos_dolorosos":
            ok = await self._instr_ecos_dolorosos(p, inst, st, data)
        elif tipo == "chamado_general":
            ok = await self._instr_chamado_general(p, inst, st, data)
        elif tipo == "dueto_marcial":
            ok = await self._instr_dueto_marcial(p, inst, st, data)
        elif tipo == "dueto_fantasma":
            ok = await self._instr_dueto_fantasma(p, inst, st, data)
        elif tipo == "requiem_final":
            ok = await self._instr_requiem_final(p, inst, st, data)
        elif tipo == "improviso":
            ok = await self._instr_improviso(p, inst, st, data)
        else:
            await self.send_to(pid, {"type": "error", "msg": "Instrumento em desenvolvimento."}); return
        if not ok:
            return

        self._pagar_fome_sede(p, st["custo_fome"], st["custo_sede"])
        p["instrumento_usado"] = True
        if duas_maos:
            p["action_done"] = True
        await self.push_state()

    async def _instr_nota_cortante(self, p, inst, st, data):
        """Alvo Ãºnico atÃ© `alcance` casas; Reflexos â†’ metade. RÃºnica: linha reta direcional."""
        if inst.get("encantamento") == "runico":
            return await self._nota_cortante_linha(p, inst, st, data)
        alvo_id = (data or {}).get("target_id")
        m = self.monsters.get(alvo_id)
        if not m or m.get("hp", 0) <= 0:
            await self.send_to(p["id"], {"type": "error", "msg": "Alvo invÃ¡lido."}); return False
        if not self._no_raio(p, m, st["alcance"]):
            await self.send_to(p["id"], {"type": "error",
                "msg": f"Alvo fora do alcance ({st['alcance']} casas)."}); return False
        await self.gm_say(f"ðŸŽµ **{p['name']}** dispara **Nota Cortante** em **{m['name']}**!")
        dano = await self._rolar_dano_mostrado(*_ndfaces(st["dano"]), "ðŸŽµ Dano sonoro")
        save_ok, *_ = await self._save_mostrado(m, "reflexos", self._instrumento_cd(p, inst))
        if save_ok:
            dano = dano // 2
        m["hp"] = max(0, m["hp"] - dano)
        await self.gm_say(f"ðŸŽµ **{m['name']}** sofre **{dano}** de dano sonoro"
                          f"{' (metade â€” resistiu)' if save_ok else ''}.")
        if m["hp"] <= 0:
            await self._monster_dies(m, p["id"])
        return True

    async def _nota_cortante_linha(self, p, inst, st, data):
        """Harpa RÃºnica: reta direcional; cada monstro na linha faz seu Reflexos-meia."""
        dirv = (data or {}).get("dir") or [0, 0]
        dx = 1 if dirv[0] > 0 else -1 if dirv[0] < 0 else 0
        dy = 1 if dirv[1] > 0 else -1 if dirv[1] < 0 else 0
        if dx == 0 and dy == 0:
            await self.send_to(p["id"], {"type": "error", "msg": "Escolha uma direÃ§Ã£o para a Nota Cortante rÃºnica."}); return False
        tiles = {tuple(t) for t in self._caminho_relampago(p["pos"], dx, dy, st["alcance"])}
        alvos = [m for m in self.monsters.values()
                 if m.get("hp", 0) > 0 and tuple(m["pos"]) in tiles]
        if not alvos:
            await self.send_to(p["id"], {"type": "error", "msg": "Nenhum inimigo na linha."}); return False
        await self.gm_say(f"ðŸŽµ **{p['name']}** dispara **Nota Cortante** numa linha reta!")
        cd = self._instrumento_cd(p, inst)
        for m in alvos:
            dano = await self._rolar_dano_mostrado(*_ndfaces(st["dano"]), "ðŸŽµ Dano sonoro")
            save_ok, *_ = await self._save_mostrado(m, "reflexos", cd)
            if save_ok:
                dano = dano // 2
            m["hp"] = max(0, m["hp"] - dano)
            await self.gm_say(f"ðŸŽµ **{m['name']}** sofre **{dano}**{' (metade)' if save_ok else ''}.")
            if m["hp"] <= 0:
                await self._monster_dies(m, p["id"])
        return True

    def _reduzir_mov_monstro(self, m, val, rodadas):
        """Reduz o movimento do monstro por `rodadas` turnos, reusando o mecanismo
        da Cola (mov_reduzido_orig/rodadas, restaurado em _processar_*_turno).
        Empilha pela MAIOR reduÃ§Ã£o e MAIOR duraÃ§Ã£o; piso 1; nunca aumenta o mov."""
        if val <= 0 or rodadas <= 0:
            return
        if "mov_reduzido_orig" not in m:
            m["mov_reduzido_orig"] = m.get("movement", 5)
        orig = m["mov_reduzido_orig"]
        novo = max(1, orig - val)
        m["movement"] = min(m.get("movement", orig), novo)
        m["mov_reduzido_rodadas"] = max(m.get("mov_reduzido_rodadas", 0), rodadas)

    async def _instr_acorde_trovejante(self, p, inst, st, data):
        """AoE centrada no bardo (raio Chebyshev). Falha: dano cheio + empurrÃ£o;
        sucesso: metade, sem empurrÃ£o. push=0 â†’ -1 movimento no lugar do empurrÃ£o."""
        alvos = [m for m in self.monsters.values()
                 if m.get("hp", 0) > 0 and self._no_raio(p, m, st["raio"])]
        if not alvos:
            await self.send_to(p["id"], {"type": "error", "msg": "Nenhum inimigo no alcance."}); return False
        await self.gm_say(f"ðŸ¥ **{p['name']}** golpeia o **Tambor de Guerra** â€” onda sonora (raio {st['raio']})!")
        cd = self._instrumento_cd(p, inst)
        for m in alvos:
            dano = await self._rolar_dano_mostrado(*_ndfaces(st["dano"]), "ðŸ¥ Dano sonoro")
            save_ok, *_ = await self._save_mostrado(m, "reflexos", cd)
            if save_ok:
                dano = dano // 2
            m["hp"] = max(0, m["hp"] - dano)
            runico = inst.get("encantamento") == "runico"
            if not save_ok:
                if st.get("push", 0) > 0:
                    dx = (m["pos"][0] > p["pos"][0]) - (m["pos"][0] < p["pos"][0])
                    dy = (m["pos"][1] > p["pos"][1]) - (m["pos"][1] < p["pos"][1])
                    self._empurrar(m, dx, dy, st["push"])
                else:
                    self._reduzir_mov_monstro(m, 1, 1)   # Tambor Velho: -1 movimento
                if runico:
                    m["perde_turno"] = True              # RÃºnico: Atordoado 1 rodada
            elif runico:
                m["acorde_atk_pen_ate"] = self.round_num + 1   # RÃºnico: -1 Ataque atÃ© o prÃ³ximo turno
            await self.gm_say(f"ðŸ¥ **{m['name']}** sofre **{dano}**"
                              f"{' (metade)' if save_ok else ''}.")
            if m["hp"] <= 0:
                await self._monster_dies(m, p["id"])
        return True

    async def _instr_ecos_dolorosos(self, p, inst, st, data):
        """Ativa a aura de retaliaÃ§Ã£o por `duracao` rodadas. Enquanto ativa, todo
        monstro que acertar o bardo em corpo a corpo sofre `dano` sonoro."""
        p["ecos_ate"] = self.round_num + st["duracao"]
