# â”€â”€â”€ Salvar definiÃ§Ãµes do editor (masmorra â†’ dungeons/, campanha â†’ campaigns/) â”€â”€
# O editor roda em file:// e o navegador nÃ£o pode gravar em pastas do PC, entÃ£o a
# definiÃ§Ã£o (JSON jÃ¡ montado) chega por WebSocket e o servidor grava na pasta
# correta â€” assim a masmorra aparece na aba de campanha sem passos manuais.
DEF_UPLOAD_MAX = 2 * 1024 * 1024               # 2 MB â€” JSON de masmorra/campanha Ã© pequeno
_BAD_FNAME = set('\\/:*?"<>|') | {"\x00"}

def _safe_def_filename(raw_id):
    """Deriva <id>.json seguro a partir do id da definiÃ§Ã£o (sem componente de dir)."""
    base = os.path.basename(str(raw_id or "")).strip()
    base = "".join("_" if c in _BAD_FNAME else c for c in base)
    if base.lower().endswith(".json"):
        base = base[:-5]
    base = base.strip(" .") or "sem_nome"
    return base + ".json"

def _gravar_def(defn, destino_dir, file):
    """Serializa e grava `defn` em destino_dir/file. Retorna (ok, msg)."""
    try:
        body = json.dumps(defn, ensure_ascii=False, indent=2)
        if len(body.encode("utf-8")) > DEF_UPLOAD_MAX:
            return False, "arquivo grande demais"
        os.makedirs(destino_dir, exist_ok=True)
        with open(os.path.join(destino_dir, file), "w", encoding="utf-8") as f:
            f.write(body)
    except OSError:
        return False, "falha ao gravar"
    return True, "ok"

def _save_dungeon_upload(defn):
    """Valida e grava uma masmorra em DUNGEONS_DIR e regenera o Ã­ndice do editor.
    Retorna (ok, {'file', 'entry'} | mensagem)."""
    if not isinstance(defn, dict):
        return False, "definiÃ§Ã£o invÃ¡lida"
    ok, msg = validar_dungeon(defn)
    if not ok:
        return False, msg
    file = _safe_def_filename(defn.get("id"))
    ok, msg = _gravar_def(defn, DUNGEONS_DIR, file)
    if not ok:
        return False, msg
    _regen_dungeons_index()
    entry = {"file": file, "id": defn.get("id", file),
             "name": defn.get("name", file), "defn": defn}
    return True, {"file": file, "entry": entry}

def _save_campaign_upload(defn):
    """Valida e grava uma campanha em CAMPAIGNS_DIR.
    Retorna (ok, {'file'} | mensagem)."""
    if not isinstance(defn, dict):
        return False, "definiÃ§Ã£o invÃ¡lida"
    ok, msg = validar_campanha(defn)
    if not ok:
        return False, msg
    file = _safe_def_filename(defn.get("id"))
    ok, msg = _gravar_def(defn, CAMPAIGNS_DIR, file)
    if not ok:
        return False, msg
    return True, {"file": file}

def _regen_dungeons_index():
    """Reescreve tools/editor_dungeons.js a partir de dungeons/ para que a aba de
    campanha do editor enxergue as masmorras salvas (inclusive apÃ³s recarregar).
    Mesma saÃ­da de tools/export_catalog.py:write_dungeons_js."""
    try:
        out = []
        for d in listar_dungeons():
            defn = carregar_dungeon(d["file"])
            if defn is None:
                continue
            out.append({"file": d["file"], "id": d["id"],
                        "name": d["name"], "defn": defn})
        payload = json.dumps(out, ensure_ascii=False, indent=2)
        txt = ("window.EDITOR_DUNGEONS = " + payload + ";\n"
               "// GERADO ao salvar no editor (e por tools/export_catalog.py).\n")
        with open(os.path.join(BASE_DIR, "tools", "editor_dungeons.js"),
                  "w", encoding="utf-8") as f:
            f.write(txt)
    except Exception:
        pass

def _serve_static(request):
    """Resolve o caminho pedido pelo navegador para um arquivo do cliente.
    Protege contra path traversal e sÃ³ expÃµe o necessÃ¡rio para jogar."""
    raw = request.path.split("?", 1)[0].split("#", 1)[0]   # tira cache-buster ?v=
    raw = urllib.parse.unquote(raw)        # %20â†’espaÃ§o etc. (nomes de mÃ­dia com espaÃ§os)
    rel = raw.lstrip("/") or "index.html"
    full = os.path.normpath(os.path.join(BASE_DIR, rel))
    # MantÃ©m dentro de BASE_DIR (bloqueia ../ e caminhos absolutos)
    if full != BASE_DIR and not full.startswith(BASE_DIR + os.sep):
        return _http(403, "Forbidden", "403 Forbidden")
    # Allow-list a partir do caminho JÃ RESOLVIDO (nÃ£o do bruto): um ../ codificado
    # pode escapar de assets/ para a raiz sem sair de BASE_DIR â€” recomputar de `full`
    # impede servir server.py via /assets/%2e%2e%2fserver.py.
    rel_norm = os.path.relpath(full, BASE_DIR).replace("\\", "/")
    top = rel_norm.split("/", 1)[0]
    if rel_norm not in _STATIC_FILES and top not in _STATIC_ROOTS:
        return _http(404, "Not Found", "404 Not Found")
    if not os.path.isfile(full):
        return _http(404, "Not Found", "404 Not Found")
    try:
        with open(full, "rb") as f:
            body = f.read()
    except OSError:
        return _http(404, "Not Found", "404 Not Found")
    ctype = mimetypes.guess_type(full)[0] or "application/octet-stream"
    if ctype.startswith("text/") or ctype in (
            "application/javascript", "application/json", "image/svg+xml"):
        ctype += "; charset=utf-8"
    return _http(200, "OK", body, ctype)

def process_request(connection, request):
    """Chamado a cada requisiÃ§Ã£o na porta do servidor. Handshake de WebSocket
    (header `Upgrade: websocket`) â†’ segue o fluxo normal de jogo (return None).
    Qualquer outra coisa Ã© um navegador pedindo a pÃ¡gina/recursos â†’ serve estÃ¡tico."""
    if request.headers.get("Upgrade", "").lower() == "websocket":
        return None
    return _serve_static(request)

# â”€â”€â”€ MAIN â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

async def main():
    # Force UTF-8 on Windows terminals (prevents UnicodeEncodeError with special chars)
    try:
        sys.stdout.reconfigure(encoding='utf-8', errors='replace')
    except (AttributeError, TypeError):
        pass

    print("=" * 60)
    print("  LEGENDS FOR HIRE - Servidor (jogo + WebSocket na mesma porta)")
    print("=" * 60)
    print("  Local:    http://localhost:8765/index.html")
    print()
    print("  Para jogar na internet (link unico para os amigos):")
    print("    1) Deixe este servidor rodando")
    print("    2) Em outro terminal abra um tunel para a porta 8765, ex.:")
    print("         cloudflared tunnel --url http://localhost:8765")
    print("         (ou: ngrok http 8765)")
    print("    3) Compartilhe o link https gerado + /index.html")
    print("  Os amigos so abrem o link, escolhem o nome e entram pelo codigo.")
    print("=" * 60)

    # process_request serve os arquivos do cliente na mesma porta â†’ um Ãºnico
    # tÃºnel https cobre pÃ¡gina + wss, sem mixed content nem digitar endereÃ§o.
    async with websockets.serve(handler, "0.0.0.0", 8765,
                                process_request=process_request,
                                max_size=34 * 1024 * 1024):
        await asyncio.Future()

if __name__ == "__main__":
    asyncio.run(main())
